<script setup lang="ts">
import { ref, computed } from 'vue'
import { useAppStore } from '../store/app'
import { ui } from '../store/ui'
import { weekStart, weekDays, shortDate, addDays, dayLabel } from '../domain/dates'
import { canCheckHabit } from '../domain/mutations'
import { streak, habitWeek } from '../domain/selectors'
import { categories } from '../domain/types'
import PageHeader from '../components/PageHeader.vue'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
const store = useAppStore(), current = ref(weekStart(store.today))
const days = computed(() => weekDays(current.value)), habits = computed(() => store.data.habits.filter(h => h.status !== 'archived'))
const summaries = computed(() => habits.value.map(h => habitWeek(store.data, h, current.value)))
const weekCount = computed(() => summaries.value.reduce((n, s) => n + s.count, 0))
const weekRate = computed(() => { const targets = summaries.value.reduce((n, s) => n + s.target, 0); return targets ? Math.round(summaries.value.reduce((n, s) => n + Math.min(s.count, s.target), 0) / targets * 100) : null })
const longest = computed(() => Math.max(0, ...habits.value.map(h => streak(store.data, h, store.today))))
const hasLog = (id: string, date: string) => store.data.habitLogs.some(l => l.habitId === id && l.date === date)
</script>
<template><PageHeader title="习惯追踪" subtitle="不追求每一天完美，只记录那些愿意坚持的小事。" eyebrow="SMALL STEPS, LASTING CHANGE"><button class="button primary" @click="ui.open('habit')"><Icon name="plus" :size="17" />新建习惯</button></PageHeader><div class="stats-grid three"><div class="stat-card"><span>本周目标达成率</span><strong>{{ weekRate === null ? '—' : `${weekRate}%` }}</strong><small>每日按 7 天，每周按设定次数</small></div><div class="stat-card"><span>当前最长连续</span><strong>{{ longest }}<small>天</small><Icon name="flame" :size="20" class="amber" /></strong><small>仅计算每日习惯，今天未打卡时看昨天</small></div><div class="stat-card"><span>本周已打卡</span><strong>{{ weekCount }}<small>次</small></strong><small>每一格，都是真实的积累</small></div></div><section class="card habit-table-card"><div class="section-heading"><h2>我的习惯</h2><div class="week-control"><button class="icon-button" aria-label="上一周" @click="current = addDays(current, -7)"><Icon name="left" :size="18" /></button><strong>{{ shortDate(days[0]!) }} — {{ shortDate(days[6]!) }}</strong><button class="icon-button" aria-label="下一周" @click="current = addDays(current, 7)"><Icon name="right" :size="18" /></button><button class="chip" @click="current = weekStart(store.today)">本周</button></div></div><div v-if="habits.length" class="habit-table-wrap"><table class="habit-table"><thead><tr><th>让成长发生的小习惯</th><th v-for="date in days" :key="date" :class="{ 'today-cell': date === store.today }"><span>{{ dayLabel(date) }}</span><small>{{ date.slice(-2) }}</small></th><th>本周</th><th>操作</th></tr></thead><tbody><tr v-for="habit in habits" :key="habit.id"><td><button class="habit-name" @click="ui.open('habit', { id: habit.id })"><span :class="['category-icon', habit.category]"><Icon :name="habit.category" /></span><span><strong>{{ habit.title }}</strong><small>{{ categories[habit.category] }} · {{ habit.frequency.kind === 'daily' ? '每天' : `每周 ${habit.frequency.times} 次` }}{{ habit.status === 'paused' ? ' · 已暂停' : '' }}</small></span></button></td><td v-for="date in days" :key="date" :class="{ 'today-cell': date === store.today }"><button :class="['habit-cell', { checked: hasLog(habit.id, date), backfill: date < store.today }]" :disabled="!canCheckHabit(store.data, habit.id, date, store.today)" :aria-label="`${hasLog(habit.id, date) ? '取消' : date < store.today ? '补打' : '打卡'} ${habit.title} ${date}`" :title="date < store.today ? '过去 7 天可补打' : date > store.today ? '未来日期不可打卡' : '今日打卡'" @click="store.toggleHabit(habit.id, date)"><Icon v-if="hasLog(habit.id, date)" name="check" :size="17" /><span v-else>·</span></button></td><td><strong>{{ habitWeek(store.data, habit, current).count }}/{{ habitWeek(store.data, habit, current).target }}</strong><div class="progress-track"><span :style="{ width: `${habitWeek(store.data, habit, current).rate || 0}%` }" /></div></td><td><button class="icon-button" :aria-label="habit.status === 'active' ? `暂停 ${habit.title}` : `恢复 ${habit.title}`" @click="habit.status = habit.status === 'active' ? 'paused' : 'active'"><Icon :name="habit.status === 'active' ? 'pause' : 'play'" :size="16" /></button><button class="icon-button" :aria-label="`编辑 ${habit.title}`" @click="ui.open('habit', { id: habit.id })"><Icon name="pencil" :size="16" /></button></td></tr></tbody></table></div><EmptyState v-else title="从一个小习惯开始" text="读两页书、走一小段路，或者睡前整理明天。"><button class="button primary" @click="ui.open('habit')">新建习惯</button></EmptyState><div class="habit-legend"><span><i class="legend-dot checked" />已打卡</span><span><i class="legend-dot" />待完成</span><span>过去 7 天可补打 · 不允许未来打卡 · 归档后历史记录保留</span></div></section><div class="gentle-note"><Icon name="health" :size="20" /><p>漏掉一天，不会失去已经走过的路。下一次开始，也值得庆祝。</p></div></template>
